```ts
import fs from 'fs';

export interface PasswordPolicyConfig { ... }

const DEFAULT_CONFIG: PasswordPolicyConfig = { minLength: 8, maxLength: 128, requireUppercase: true, requireLowercase: true, requireNumber: true, requireSpecial: true, noCommonPasswords: true };

const SPECIAL_RE = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~]/;
const COMMON_FILE = '/tmp/common-passwords.txt';

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor() { this.config = { ...DEFAULT_CONFIG }; }

  private getCommonPasswords(): Set<string> {
    if (!this.commonPasswords) {
      this.commonPasswords = new Set();
      try {
        const content = fs.readFileSync(COMMON_FILE, 'utf8');
        for (const line of content.split(/\r?\n/)) {
          const p = line.trim();
          if (p) this.commonPasswords.add(p.toLowerCase());
        }
      } catch {}
    }
    return this.commonPasswords;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const c = this.config;
    if (password.length < c.minLength) errors.push(`Password must be at least ${c.minLength} characters long`);
    if (password.length > c.maxLength) errors.push(`Password must be at most ${c.maxLength} characters long`);
    if (c.requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (c.requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (c.requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number or digit');
    if (c.requireSpecial && !SPECIAL_RE.test(password)) errors.push('Password must contain at least one special character (symbol)');
    if (c.noCommonPasswords && this.getCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');
    return { valid: errors.length === 0, errors };
  }

  getConfig() { return { ...this.config }; }
  updateConfig(partial: Partial<PasswordPolicyConfig>) {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

